type attemptResult struct {
	body       []byte
	status     int
	response   *http.Response
	err        error
	retryable  bool
	retryAfter time.Duration
}

// attempt performs one HTTP round trip.
func (c *Client) attempt(ctx context.Context, req *request, endpoint string, attempt int, timeout time.Duration) attemptResult {
	cfg := c.cfg

	cancel := context.CancelFunc(func() {})
	expire := func() {}
	keep := false
	switch {
	case req.stream:
		// The timeout only covers opening a stream, which then lives until closed.
		var cancelCause context.CancelCauseFunc
		ctx, cancelCause = context.WithCancelCause(ctx)
		cancel = func() { cancelCause(context.Canceled) }
		expire = func() { cancelCause(context.DeadlineExceeded) }
		if timeout > 0 {
			defer time.AfterFunc(timeout, expire).Stop()
		}
	case timeout > 0:
		ctx, cancel = context.WithTimeout(ctx, timeout)
	}
	defer func() {
		if !keep {
			cancel()
		}
	}()

	var body io.Reader
	if req.body != nil {
		body = bytes.NewReader(req.body)
	} else if req.newBody != nil {
		var err error
		if body, err = req.newBody(); err != nil {
			return attemptResult{err: requestError("reading request body: %w", err)}
		}
	}

	httpReq, err := http.NewRequestWithContext(ctx, req.method, endpoint, body)
	if err != nil {
		return attemptResult{err: requestError("building request: %w", err)}
	}

	for name, values := range req.headers {
		for _, value := range values {
			httpReq.Header.Add(name, value)
		}
	}
	if req.contentType != "" {
		httpReq.Header.Set("Content-Type", req.contentType)
	}
	setDefault(httpReq.Header, "Accept", "application/json")
	setDefault(httpReq.Header, "User-Agent", cfg.userAgent)
	if attempt > 0 {
		httpReq.Header.Set("@@HEADER_PREFIX@@-retry-count", strconv.Itoa(attempt))
	}

	if cfg.logger != nil {
		cfg.logger.DebugContext(ctx, "@@PACKAGE_NAME@@: request", "method", req.method, "url", endpoint, "attempt", attempt+1)
	}

	resp, err := cfg.httpClient.Do(httpReq)
	if err != nil {
		return attemptResult{retryable: true, err: failure(ctx, req, err)}
	}
	if req.stream && resp.StatusCode >= 200 && resp.StatusCode < 300 {
		keep = true
		req.response, req.cancel, req.expire, req.timeout = resp, cancel, expire, timeout
		req.fail = func(err error) error { return failure(ctx, req, err) }
		return attemptResult{status: resp.StatusCode, response: resp}
	}
	defer func() { _ = resp.Body.Close() }()

	respBody, err := io.ReadAll(resp.Body)
	if err != nil {
		return attemptResult{retryable: true, err: failure(ctx, req, fmt.Errorf("reading response body: %w", err))}
	}
	read := *resp
	read.Body = io.NopCloser(bytes.NewReader(respBody))

	if cfg.logger != nil {
		cfg.logger.DebugContext(ctx, "@@PACKAGE_NAME@@: response", "method", req.method, "url", endpoint, "status", resp.StatusCode, "bytes", len(respBody))
	}

	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		apiErr := newResponseError(req.method, req.path, resp.StatusCode, resp.Header, respBody)
		apiErr.Body = req.errors.decode(resp.StatusCode, respBody)
		return attemptResult{
			status:     resp.StatusCode,
			response:   &read,
			err:        apiErr,
			retryable:  retryableStatus(resp.StatusCode),
			retryAfter: retryAfter(resp.Header, time.Now()),
		}
	}

	return attemptResult{body: respBody, status: resp.StatusCode, response: &read}
}

// failure is the error of an attempt that got no response: a [*TimeoutError]
// when it ran out of time, else a [*TransportError].
func failure(ctx context.Context, req *request, err error) error {
	var netErr net.Error
	if (errors.As(err, &netErr) && netErr.Timeout()) || errors.Is(context.Cause(ctx), context.DeadlineExceeded) {
		return &TimeoutError{Method: req.method, Path: req.path, Err: err}
	}
	return &TransportError{Method: req.method, Path: req.path, Err: err}
}

// retryableStatus reports whether a failed status may succeed later: timeouts,
// rate limits and server errors. Other 4xx fail again the same way.
func retryableStatus(status int) bool {
	return status == http.StatusRequestTimeout || status == http.StatusTooManyRequests || status >= 500
}

// retryAfter reads how long the server asks to wait, from retry-after-ms or
// Retry-After.
func retryAfter(header http.Header, now time.Time) time.Duration {
	if ms, err := strconv.ParseFloat(header.Get("Retry-After-Ms"), 64); err == nil && ms > 0 {
		return time.Duration(ms * float64(time.Millisecond))
	}
	return parseRetryAfter(header.Get("Retry-After"), now)
}

// parseRetryAfter reads a Retry-After header, in seconds or as an HTTP date.
func parseRetryAfter(value string, now time.Time) time.Duration {
	if value == "" {
		return 0
	}
	if seconds, err := strconv.ParseFloat(value, 64); err == nil && seconds > 0 {
		return time.Duration(seconds * float64(time.Second))
	}
	if at, err := http.ParseTime(value); err == nil && at.After(now) {
		return at.Sub(now)
	}
	return 0
}

func setDefault(header http.Header, name, value string) {
	if header.Get(name) == "" {
		header.Set(name, value)
	}
}

// jsonValue round-trips v through its JSON representation, so that the `json` tags
// of the generated models stay the single source of truth for wire names.
func jsonValue(v any) (any, error) {
	encoded, err := json.Marshal(v)
	if err != nil {
		return nil, err
	}
	decoder := json.NewDecoder(bytes.NewReader(encoded))
	decoder.UseNumber()
	var value any
	if err := decoder.Decode(&value); err != nil {
		return nil, err
	}
	return value, nil
}

func isNested(value any) bool {
	switch value.(type) {
	case map[string]any, []any:
		return true
	}
	return false
}

func paramText(value any) (string, bool) {
	switch typed := value.(type) {
	case string:
		return typed, true
	case bool:
		return strconv.FormatBool(typed), true
	case json.Number:
		return typed.String(), true
	}
	return "", false
}

// encodeParam adds one JSON value the way Stripe-style APIs read nested values:
// name[key]=value, name[]=item for lists of scalars, name[0][key]=value for lists
// of objects. Top-level lists of scalars repeat name unless deepObject or not explode.
func encodeParam(name string, value any, deepObject, explode bool, out url.Values) {
	if list, ok := value.([]any); ok && !deepObject && !slices.ContainsFunc(list, isNested) {
		texts := make([]string, 0, len(list))
		for _, item := range list {
			if text, ok := paramText(item); ok {
				texts = append(texts, text)
			}
		}
		if explode {
			for _, text := range texts {
				out.Add(name, text)
			}
		} else if len(texts) > 0 {
			out.Add(name, strings.Join(texts, ","))
		}
		return
	}
	flattenParam(name, value, out)
}

func flattenParam(prefix string, value any, out url.Values) {
	switch typed := value.(type) {
	case map[string]any:
		for key, item := range typed {
			flattenParam(prefix+"["+key+"]", item, out)
		}
	case []any:
		for index, item := range typed {
			if isNested(item) {
				flattenParam(prefix+"["+strconv.Itoa(index)+"]", item, out)
			} else if text, ok := paramText(item); ok {
				out.Add(prefix+"[]", text)
			}
		}
	default:
		if text, ok := paramText(value); ok {
			out.Add(prefix, text)
		}
	}
}

func randomHex(n int) (string, error) {
	buf := make([]byte, n)
	if _, err := rand.Read(buf); err != nil {
		return "", requestError("reading random bytes: %w", err)
	}
	return hex.EncodeToString(buf), nil
}

// Query parameter formatting helpers used by the generated resource methods.

func formatBool(v bool) string { return strconv.FormatBool(v) }

func formatInt(v int64) string { return strconv.FormatInt(v, 10) }

func formatUint(v uint64) string { return strconv.FormatUint(v, 10) }

func formatFloat(v float64) string { return strconv.FormatFloat(v, 'f', -1, 64) }

func formatTime(v time.Time) string { return v.UTC().Format(time.RFC3339Nano) }

// formatValue formats a named type: enums through String, aliases as their value.
func formatValue(v any) string {
	switch v := v.(type) {
	case time.Time:
		return formatTime(v)
	case fmt.Stringer:
		return v.String()
	default:
		return fmt.Sprint(v)
	}
}

// jsonField is a struct field whose JSON name `encoding/json` cannot carry in a
// struct tag (a quote, backslash or comma in it), encoded and decoded by hand.
type jsonField struct {
	Name  string
	Value any
	Omit  bool
}

// marshalWithFields encodes base, a struct, and appends the fields its tags
// cannot name to the resulting object.
func marshalWithFields(base any, fields []jsonField) ([]byte, error) {
	data, err := json.Marshal(base)
	if err != nil {
		return nil, err
	}
	data = bytes.TrimSpace(data)
	if len(data) < 2 || data[0] != '{' || data[len(data)-1] != '}' {
		return nil, fmt.Errorf("@@PACKAGE_NAME@@: %T must encode to a JSON object", base)
	}
	out := append([]byte(nil), data[:len(data)-1]...)
	empty := len(bytes.TrimSpace(data[1:len(data)-1])) == 0
	for _, field := range fields {
		if field.Omit {
			continue
		}
		key, err := json.Marshal(field.Name)
		if err != nil {
			return nil, err
		}
		value, err := json.Marshal(field.Value)
		if err != nil {
			return nil, err
		}
		if !empty {
			out = append(out, ',')
		}
		empty = false
		out = append(append(append(out, key...), ':'), value...)
	}
	return append(out, '}'), nil
}

// unmarshalFields decodes the members of the JSON object data named in targets
// into the pointers they map to, leaving targets whose member is absent as is.
func unmarshalFields(data []byte, targets map[string]any) error {
	var members map[string]json.RawMessage
	if err := json.Unmarshal(data, &members); err != nil {
		return err
	}
	for name, target := range targets {
		if raw, ok := members[name]; ok {
			if err := json.Unmarshal(raw, target); err != nil {
				return fmt.Errorf("@@PACKAGE_NAME@@: field %q: %w", name, err)
			}
		}
	}
	return nil
}

// marshalUnionVariant encodes a tagged union: the variant payload and the fields
// the variants share are merged into one object, with the discriminator.
func marshalUnionVariant(tagField, tagValue string, payload any, shared ...any) ([]byte, error) {
	fields := map[string]json.RawMessage{}
	for _, part := range append([]any{payload}, shared...) {
		encoded, err := json.Marshal(part)
		if err != nil {
			return nil, err
		}
		if err := json.Unmarshal(encoded, &fields); err != nil {
			return nil, fmt.Errorf("@@PACKAGE_NAME@@: union variant %q must encode to a JSON object: %w", tagValue, err)
		}
	}
	if fields == nil {
		fields = map[string]json.RawMessage{}
	}

	tag, err := json.Marshal(tagValue)
	if err != nil {
		return nil, err
	}
	fields[tagField] = tag

	return json.Marshal(fields)
}

// jsonKind names the JSON type of an encoded value, as union variants declare it.
func jsonKind(data []byte) string {
	trimmed := bytes.TrimLeft(data, " \t\r\n")
	if len(trimmed) == 0 {
		return ""
	}
	switch c := trimmed[0]; {
	case c == '"':
		return "string"
	case c == '{':
		return "object"
	case c == '[':
		return "array"
	case c == 't' || c == 'f':
		return "boolean"
	case c == 'n':
		return "null"
	case c == '-' || (c >= '0' && c <= '9'):
		return "number"
	}
	return ""
}
